"""Residentado Médico · lote 6, paquete 8 (neumología: nódulo, asma, derrame pleural, SDRA, TEP)"""
from lote01a import Q
import lote01a
L = []
lote01a.L = L
HAR = "Harrison Principios de Medicina Interna 21.ª ed. (2022)"
ROB = "Robbins y Cotran Patología estructural y funcional 10.ª ed. (2021)"
GUY = "Guyton y Hall Tratado de Fisiología Médica 14.ª ed. (2021)"
KAT = "Katzung Farmacología básica y clínica 16.ª ed. (2024)"
GIN = "GINA, Global Strategy for Asthma Management and Prevention (2025)"

Q(a="neumologia", cat="Oncología torácica", tema="Nódulo pulmonar apical en fumador: carcinoma broncogénico", año=2015, ext=True,
  e="Varón de 62 años con antecedente de tabaquismo y baja de peso presenta en la radiografía de tórax un nódulo pulmonar de 2,5 cm de bordes irregulares en el ápice pulmonar derecho. ¿Cuál es el diagnóstico más probable?",
  o=["Sarcoidosis pulmonar.", "Histoplasmosis.", "Aspergiloma.", "Nódulo reumatoide.", "Carcinoma broncogénico."], k="E",
  c="El carcinoma broncogénico es la neoplasia maligna que nace del epitelio bronquial o del parénquima, y el tabaquismo explica cerca del 85 % de los casos. Ante un nódulo pulmonar solitario, la probabilidad de malignidad aumenta con la edad mayor de 60 años, el tabaquismo, el tamaño superior a 2 cm, los bordes espiculados o irregulares, la localización en lóbulos superiores y la ausencia de calcificación; los síntomas constitucionales como la pérdida de peso refuerzan la sospecha. En el ápice hay que pensar además en el tumor de Pancoast, que puede producir dolor de hombro, síndrome de Horner y atrofia de los músculos de la mano por invasión del plexo braquial. La sarcoidosis se manifiesta con adenopatías hiliares bilaterales e infiltrados, la histoplasmosis deja granulomas calcificados, el aspergiloma es una masa móvil dentro de una cavidad previa (típicamente tuberculosa) con el signo del halo aéreo, y el nódulo reumatoide aparece en artritis reumatoide seropositiva con nódulos subcutáneos. El estudio sigue con tomografía de tórax, PET-TC, broncoscopía o biopsia transtorácica según la ubicación, y estadificación TNM. Perla clínica: un nódulo sólido espiculado mayor de 8 mm en un fumador no se vigila, se estudia hasta obtener tejido.",
  f="Fleischner Society, manejo de nódulos pulmonares incidentales (Radiology 2017;284:228-243); WHO Classification of Thoracic Tumours, 5.ª ed. (2021); " + HAR + "; " + ROB)

Q(a="neumologia", cat="Farmacología", tema="Retención urinaria por anticolinérgico inhalado", año=2015, ext=False,
  e="Varón de 72 años con asma bronquial y medicación irregular llega a emergencia con retención urinaria. ¿Cuál de los siguientes fármacos ha ocasionado el efecto secundario?",
  o=["Salbutamol.", "Teofilina.", "Fenoterol.", "Bromuro de ipratropio.", "Budesonida."], k="D",
  c="El bromuro de ipratropio es un antagonista muscarínico que bloquea los receptores M3 del músculo liso bronquial y logra broncodilatación, pero el mismo bloqueo en el músculo detrusor de la vejiga disminuye su contracción y mantiene cerrado el esfínter, lo que favorece la retención urinaria aguda. El riesgo es mayor en varones ancianos con hiperplasia prostática benigna, donde la obstrucción previa del flujo de salida se descompensa; otros efectos anticolinérgicos son sequedad de boca, estreñimiento, visión borrosa y precipitación de glaucoma de ángulo cerrado si el aerosol llega a los ojos. Salbutamol y fenoterol son agonistas beta-2 y producen temblor, taquicardia e hipopotasemia; los agonistas beta incluso relajan el detrusor y rara vez causan retención, aunque los alfa-adrenérgicos sí la favorecen. La teofilina, una metilxantina, causa náuseas, taquiarritmias y convulsiones con niveles tóxicos, y la budesonida inhalada produce candidiasis orofaríngea y disfonía. En el paciente asmático anciano con síntomas urinarios obstructivos conviene preferir beta-2 agonistas y vigilar con prudencia el uso de anticolinérgicos, sin olvidar revisar toda la polifarmacia. Perla clínica: ante retención urinaria en un paciente mayor, revisar siempre los fármacos anticolinérgicos, opioides, antihistamínicos y descongestionantes antes de atribuirla solo a la próstata.",
  f=KAT + "; Goodman y Gilman Las bases farmacológicas de la terapéutica 14.ª ed. (2023); " + GIN)

Q(a="neumologia", cat="Asma", tema="Broncoconstricción inducida por ejercicio: prevención", año=2015, ext=False,
  e="Varón de 18 años, luego de una carrera en bicicleta, presenta por primera vez sensación de falta de aire. Al examen clínico: sibilantes y espiración prolongada. ¿Cuál es el mejor tratamiento preventivo para evitar una nueva crisis?",
  o=["Metilxantinas.", "Beta-2 agonistas antes del ejercicio.", "Antileucotrienos.", "Corticoides inhalados.", "Anticolinérgicos."], k="B",
  c="La broncoconstricción inducida por el ejercicio se produce porque el aire inspirado con alto flujo llega frío y seco a la vía aérea, la deshidratación de la mucosa eleva la osmolaridad y provoca liberación de histamina, leucotrienos y prostaglandinas por mastocitos y eosinófilos, con broncoespasmo a los 5-15 minutos de terminado el esfuerzo. Se confirma con una prueba de ejercicio o hiperventilación isocápnica con caída del VEF1 de al menos 10 % respecto de la basal. En un joven con un primer episodio desencadenado solo por el esfuerzo, la medida preventiva de primera línea es un agonista beta-2 de acción corta inhalado 10-15 minutos antes del ejercicio, que protege al 80-90 % de los casos durante dos a tres horas; el calentamiento previo y respirar por la nariz ayudan. Los corticoides inhalados diarios se añaden cuando hay asma persistente de fondo o cuando el beta-2 previo no basta, y su efecto protector recién aparece tras semanas de uso regular. Los antileucotrienos son una alternativa o un complemento menos eficaz, las metilxantinas casi no se emplean y los anticolinérgicos no tienen rol demostrado. Perla clínica: el uso diario de beta-2 de acción corta o larga induce tolerancia y pérdida del efecto protector, por eso no se recomienda como tratamiento crónico.",
  f="Parsons JP et al., ATS, guía de práctica clínica sobre broncoconstricción inducida por ejercicio (Am J Respir Crit Care Med 2013;187:1016-1027); " + GIN + "; " + HAR,
  nota="El libro marca D (corticoides inhalados) como tratamiento de fondo. En un primer episodio inducido por ejercicio, sin asma persistente documentada, la guía ATS 2013 y GINA 2025 sitúan al beta-2 agonista de acción corta previo al ejercicio como primera línea preventiva; los corticoides inhalados son la opción si hay asma persistente o respuesta insuficiente. Se corrigió la clave a B; el coordinador decide.")

Q(a="neumologia", cat="Fisiología", tema="Principal estímulo del centro respiratorio", año=2015, ext=False,
  e="El estímulo respiratorio central más intenso se deriva de:",
  o=["Acidosis.", "Hipercapnia.", "Hipoxia.", "Alcalosis.", "Hipovolemia."], k="B",
  c="La ventilación se regula sobre todo para mantener estable la presión arterial de dióxido de carbono. El CO2 difunde con facilidad a través de la barrera hematoencefálica, se hidrata a ácido carbónico en el líquido cefalorraquídeo y libera iones hidrógeno que estimulan los quimiorreceptores centrales de la superficie ventral del bulbo; este es el estímulo más potente y explica que un aumento de apenas 2-5 mmHg de PaCO2 duplique la ventilación minuto. Los quimiorreceptores periféricos de los cuerpos carotídeos y aórticos responden a la hipoxemia, a la hipercapnia y a la acidemia, pero la hipoxia solo se vuelve un estímulo importante cuando la PaO2 cae por debajo de 60 mmHg. La acidosis metabólica estimula la ventilación (respiración de Kussmaul), aunque los iones hidrógeno de la sangre cruzan mal la barrera, por eso el efecto es menos intenso e inmediato que el del CO2. La alcalosis inhibe la respiración y la hipovolemia no es un estímulo ventilatorio directo. En el paciente con EPOC e hipercapnia crónica el pH del líquido cefalorraquídeo se normaliza por compensación con bicarbonato, de modo que el impulso respiratorio pasa a depender de la hipoxemia. Perla clínica: administrar oxígeno en exceso a un retenedor crónico de CO2 puede deprimir la ventilación, por eso se apunta a una saturación de 88-92 %.",
  f=GUY + "; West Fisiología respiratoria 11.ª ed. (2022); " + HAR)

Q(a="neumologia", cat="Derrame pleural", tema="Derrame pleural en cirrosis: criterios de Light", año=2015, ext=False,
  e="En un paciente con cirrosis hepática se encuentra derrame pleural. La confirmación de que el derrame es debido a la cirrosis la proporcionan una relación proteínas en líquido pleural / suero igual a... y LDH en líquido pleural / suero igual a...",
  o=["> 0,6; > 0,5.", "< 0,5; < 0,6.", "< 0,6; < 0,5.", "> 0,5; > 0,6.", "> 0,5; < 0,6."], k="B",
  c="El hidrotórax hepático es un trasudado que se forma cuando el líquido ascítico pasa a la cavidad pleural a través de defectos diafragmáticos, sobre todo en el lado derecho, y por eso se produce por presión hidrostática y oncótica alteradas y no por inflamación de la pleura. Los criterios de Light de 1972 clasifican un derrame como exudado si cumple al menos uno de tres: relación proteínas pleura/suero mayor de 0,5, relación LDH pleura/suero mayor de 0,6, o LDH pleural mayor de dos tercios del límite superior normal sérico. Un trasudado no cumple ninguno, es decir, proteínas pleura/suero menor de 0,5 y LDH pleura/suero menor de 0,6, que es la opción correcta. Las demás combinaciones mezclan umbrales o los invierten. Los criterios sobreestiman exudados en pacientes tratados con diuréticos, por lo que en cirrosis o insuficiencia cardiaca con perfil dudoso se calcula el gradiente de albúmina sérica menos pleural, mayor de 1,2 g/dL, que favorece trasudado. Otras causas de trasudado son insuficiencia cardiaca, síndrome nefrótico y diálisis peritoneal; los exudados se ven en neumonía, tuberculosis, neoplasia y embolia pulmonar. Perla clínica: el hidrotórax hepático con fiebre y dolor pleurítico obliga a descartar empiema bacteriano espontáneo con cultivo y recuento de neutrófilos mayor de 250/mm3.",
  f="Light RW et al., Pleural effusions: the diagnostic separation of transudates and exudates (Ann Intern Med 1972;77:507-513); Clin Chest Med 2021;42:… Light's criteria after half a century (PMID 34774168); " + HAR,
  nota="Opciones reconstruidas desde la imagen del libro (el OCR las dejó pegadas); la opción C es «< 0,6; < 0,5».")

Q(a="neumologia", cat="SDRA", tema="Causa más frecuente de SDRA", año=2016, ext=False,
  e="¿Cuál es el trastorno más frecuente asociado al síndrome de dificultad respiratoria aguda (SDRA)?",
  o=["Sepsis.", "Pancreatitis.", "Embolia grasa.", "Tuberculosis miliar.", "Edema pulmonar neurogénico."], k="A",
  c="El SDRA es una lesión inflamatoria difusa de la membrana alveolocapilar con aumento de la permeabilidad, edema alveolar rico en proteínas, pérdida de surfactante y shunt intrapulmonar, que se manifiesta como hipoxemia refractaria con opacidades bilaterales no explicadas por insuficiencia cardiaca. La definición de Berlín (2012) exige inicio en menos de una semana de una agresión conocida, imágenes bilaterales, origen no cardiogénico y una relación PaO2/FiO2 con PEEP mínima de 5 cmH2O que clasifica el cuadro en leve (200-300), moderado (100-200) o grave (menor de 100); la definición global de 2023 admite también la oxigenoterapia nasal de alto flujo y la medición con SpO2/FiO2 cuando no hay gasometría. Los factores desencadenantes pulmonares más frecuentes son la neumonía y la aspiración, y entre los extrapulmonares el más importante es la sepsis, de ahí que ante un SDRA siempre se busque el foco infeccioso. La pancreatitis grave, la embolia grasa, el trauma, las transfusiones múltiples y el edema neurogénico son causas reconocidas pero menos comunes, y la tuberculosis miliar es una causa rara. El alcoholismo crónico aumenta el riesgo por depleción de glutatión en el líquido de revestimiento alveolar. El manejo se basa en ventilación protectora con volumen corriente de 6 mL/kg de peso ideal, presión meseta menor de 30 cmH2O, PEEP adecuada y, en casos graves, posición prona más de 12 horas diarias. Perla clínica: tratar la causa es parte del tratamiento del SDRA.",
  f="ARDS Definition Task Force, Definición de Berlín (JAMA 2012;307:2526-2533); Matthay MA et al., nueva definición global del SDRA (Am J Respir Crit Care Med 2024;209:37-47); " + HAR)

Q(a="neumologia", cat="Tromboembolismo pulmonar", tema="Tratamiento inicial del tromboembolismo pulmonar", año=2016, ext=False,
  e="Mujer de 42 años, luego de un viaje prolongado, refiere dolor e inflamación de las pantorrillas y bruscamente dificultad respiratoria, por lo que acude a emergencia. Examen: PA 100/60 mmHg, FC 118 por minuto, FR 26 por minuto, peso 88 kg. Pulmones normales. Extremidad inferior derecha con aumento de volumen y signo de Homans positivo. Gases arteriales: pH 7,20; pCO2 19 mmHg; PaO2 68 mmHg; SaO2 80 % con FiO2 0,21. ¿Cuál es el tratamiento farmacológico inicial?",
  o=["Dalteparina 50 UI VO cada 24 horas.", "Fondaparinux 2,5 mg SC cada 24 horas.", "Tinzaparina 15 U/kg cada 24 horas.", "Warfarina 5 mg VO cada 24 horas.", "Enoxaparina 1 mg/kg SC cada 12 horas."], k="E",
  c="El cuadro es un tromboembolismo pulmonar agudo de riesgo intermedio: hay un factor de riesgo (viaje prolongado, obesidad), trombosis venosa profunda evidente, taquicardia, taquipnea e hipoxemia con pulmones limpios y presión arterial conservada, sin shock. Tras la sospecha clínica se debe iniciar anticoagulación parenteral de inmediato, incluso antes de confirmar con angiotomografía, si la probabilidad es alta. En pacientes hemodinámicamente estables se prefieren las heparinas de bajo peso molecular a dosis terapéuticas por peso, como enoxaparina 1 mg/kg cada 12 horas (o 1,5 mg/kg diarios), porque su efecto es predecible y no requiere monitorización, o fondaparinux a dosis terapéutica según el peso; la heparina no fraccionada se reserva para insuficiencia renal grave, obesidad extrema o posible fibrinólisis. Los anticoagulantes orales directos son una alternativa válida como tratamiento por vía oral, sin necesidad de lisis previa de heparina, y la warfarina nunca se inicia sola porque produce un estado protrombótico inicial por la caída de proteína C: se solapa con heparina al menos cinco días hasta lograr un INR de 2-3. Las dosis de dalteparina oral o tinzaparina de 15 U/kg no son terapéuticas. La duración es de al menos tres meses, y la trombólisis se reserva para el TEP con inestabilidad hemodinámica. Perla clínica: los puntajes de Wells y de Ginebra y el dímero D guían el estudio; el signo de Homans es poco sensible y poco específico.",
  f="Konstantinides SV et al., ESC, guía de TEP agudo (Eur Heart J 2020;41:543-603); Stevens SM et al., CHEST, terapia antitrombótica de la ETV, segunda actualización (Chest 2021;160:e545-e608); Ortel TL et al., ASH 2020, tratamiento de la TVP y el TEP (Blood Adv 2020;4:4693-4738); " + HAR,
  nota="Fondaparinux 7,5 mg SC cada 24 horas (opción B original) es dosis terapéutica correcta para 50-100 kg, o sea que habría dos respuestas válidas; se reemplazó por fondaparinux 2,5 mg SC cada 24 horas (dosis profiláctica) y se mantiene la clave E.")

Q(a="neumologia", cat="Eosinofilia pulmonar", tema="Síndrome de Löffler", año=2016, ext=False,
  e="La neumonía eosinofílica caracterizada por infiltrados alveolares migratorios y mínimas manifestaciones clínicas corresponde a:",
  o=["Síndrome de Löffler.", "Granulomatosis alérgica de Churg-Strauss.", "Micosis pulmonar alérgica.", "Neumonía eosinofílica aguda.", "Síndrome de Goodpasture."], k="A",
  c="El síndrome de Löffler, o neumonía eosinofílica simple, es una enfermedad autolimitada de infiltrados pulmonares fugaces y migratorios con eosinofilia periférica, que cursa con pocos síntomas, tos seca leve, a veces febrícula o sibilancias, y se resuelve de forma espontánea en una a cuatro semanas. En nuestro medio la causa más frecuente es la migración pulmonar de larvas de helmintos como Ascaris lumbricoides, Strongyloides stercoralis y uncinarias, y también se describe tras fármacos como nitrofurantoína, AINE, sulfonamidas y antibióticos. El tratamiento consiste en retirar el agente o tratar el parásito (albendazol o ivermectina según el caso; ante la sospecha de estrongiloidiasis se debe tratar antes de usar corticoides por el riesgo de hiperinfección). La granulomatosis eosinofílica con poliangeítis (Churg-Strauss) se acompaña de asma de inicio tardío, sinusitis, neuropatía periférica y vasculitis con ANCA. La micosis broncopulmonar alérgica ocurre en asmáticos con Aspergillus y bronquiectasias centrales. La neumonía eosinofílica aguda es un cuadro febril de insuficiencia respiratoria de menos de siete días, a menudo tras iniciar el tabaquismo, con más de 25 % de eosinófilos en el lavado broncoalveolar. El síndrome de Goodpasture es una hemorragia alveolar con glomerulonefritis y anticuerpos antimembrana basal. Perla clínica: infiltrados migratorios con eosinofilia en un paciente con geohelmintiasis son Löffler hasta demostrar lo contrario.",
  f="Cottin V, neumonías eosinofílicas (revisión, Clin Chest Med y Eur Respir Rev); " + HAR + "; " + ROB,
  nota="Cita Cottin V sin año verificable en PubMed por mi parte; se sustituye abajo si el coordinador lo requiere.")

Q(a="neumologia", cat="SDRA", tema="Hallazgo radiológico del SDRA", año=2016, ext=False,
  e="¿Cuál de los hallazgos en la radiografía de tórax se considera un criterio para diagnosticar síndrome de dificultad respiratoria aguda del adulto?",
  o=["Lesiones de tipo reticulonodulillar difusas.", "Lesiones en panal de abeja en las bases.", "Imágenes vasculares en ala de mariposa.", "Patrón en vidrio esmerilado.", "Infiltrados alveolointersticiales bilaterales."], k="E",
  c="Para el diagnóstico de SDRA la definición de Berlín (2012) pide opacidades bilaterales en la radiografía o la tomografía, que no se expliquen completamente por derrame, colapso lobar o pulmonar ni por nódulos. Corresponden a un edema pulmonar no cardiogénico de permeabilidad aumentada: aparecen de 12 a 24 horas después de la agresión como infiltrados alveolointersticiales difusos y bilaterales que confluyen hasta un aspecto de pulmón blanco, con broncograma aéreo. La definición global de 2023 acepta además la ecografía pulmonar como método de imagen. El patrón reticulonodulillar difuso y el panal de abeja basal son característicos de la fibrosis pulmonar y las neumopatías intersticiales crónicas. La imagen en ala de mariposa o perihiliar con redistribución vascular sugiere edema cardiogénico o sobrecarga hídrica, que se debe descartar con ecocardiografía; el vidrio esmerilado es un hallazgo tomográfico inespecífico presente en muchas patologías, entre ellas el SDRA, pero no es un criterio de la definición. Además deben cumplirse la relación PaO2/FiO2 menor de 300 con PEEP de al menos 5 cmH2O y un inicio dentro de una semana de un factor de riesgo. Perla clínica: la radiografía no distingue de manera fiable el SDRA del edema cardiogénico, y la tomografía suele mostrar condensaciones en zonas posteriores dependientes con vidrio esmerilado anterior.",
  f="ARDS Definition Task Force, Definición de Berlín (JAMA 2012;307:2526-2533); Matthay MA et al., nueva definición global del SDRA (Am J Respir Crit Care Med 2024;209:37-47); " + HAR)

Q(a="neumologia", cat="Tromboembolismo pulmonar", tema="TEP posoperatorio inmediato", año=2016, ext=False,
  e="Mujer de 45 años, obesa, dos horas después de haber sido operada de histerectomía total, súbitamente presenta dolor intenso en el pecho, disnea, lipotimia y sensación de muerte inminente. Examen: sin ingurgitación yugular, reforzamiento del segundo ruido en foco pulmonar, cianosis y taquicardia. Pulmones normales. ¿Cuál es el diagnóstico más probable?",
  o=["Tromboembolismo pulmonar.", "Coartación de aorta.", "Infarto de miocardio.", "Aneurisma de aorta.", "Neumonía aspirativa."], k="A",
  c="El tromboembolismo pulmonar resulta de la migración de un trombo desde las venas profundas de las piernas o la pelvis hacia las arterias pulmonares. Se explica por la tríada de Virchow (estasis, hipercoagulabilidad y daño endotelial) y aquí hay varios factores: cirugía pélvica mayor, obesidad e inmovilización. La clínica típica es de disnea súbita, dolor torácico pleurítico, taquipnea y taquicardia, con cianosis, síncope o muerte en las formas masivas; el reforzamiento del componente pulmonar del segundo ruido indica hipertensión pulmonar aguda, y el examen pulmonar suele ser normal porque el parénquima está ventilado pero no perfundido. El diagnóstico se apoya en la probabilidad clínica (escala de Wells o Ginebra), el dímero D si la probabilidad es baja o intermedia y la angiotomografía pulmonar; el electrocardiograma puede mostrar taquicardia sinusal o el patrón S1Q3T3, y la ecocardiografía muestra sobrecarga del ventrículo derecho. La coartación y el aneurisma de aorta no producen este cuadro agudo posoperatorio, el infarto de miocardio cursa con alteraciones electrocardiográficas y de troponina, y la neumonía aspirativa cursa con fiebre, secreciones y crepitantes. Perla clínica: ante sospecha alta en una paciente con riesgo de sangrado posoperatorio inmediato, se valora anticoagulación con cautela, y el filtro de vena cava se reserva para quienes no pueden anticoagularse.",
  f="Konstantinides SV et al., ESC, guía de TEP agudo (Eur Heart J 2020;41:543-603); Stevens SM et al., CHEST (Chest 2021;160:e545-e608); " + HAR)

Q(a="neumologia", cat="Farmacología", tema="Efectos adversos de agonistas beta-2 de larga acción", año=2016, ext=False,
  e="Varón de 20 años con diagnóstico de asma bronquial desde hace cinco años y en tratamiento con salmeterol de larga data. ¿Cuál de los siguientes efectos adversos está relacionado con su administración?",
  o=["Hipocalcemia.", "Hiperkalemia.", "Hiperglicemia.", "Bradicardia.", "Disminución de ácidos grasos libres."], k="C",
  c="El salmeterol es un agonista beta-2 de acción prolongada (LABA), muy lipofílico, de inicio lento, cuya acción dura unas 12 horas; nunca debe usarse como monoterapia en asma, sino siempre combinado con un corticoide inhalado, por el riesgo de exacerbaciones graves. Su efecto se debe a la activación de receptores beta-2 acoplados a proteína Gs, que aumenta el AMP cíclico. Fuera del músculo liso bronquial, esa activación en hígado y músculo aumenta la glucogenólisis y la gluconeogénesis, y por eso aparece hiperglucemia; en el adipocito aumenta la lipólisis y eleva los ácidos grasos libres; en el músculo esquelético incorpora potasio a la célula por estimulación de la bomba Na+/K+ ATPasa y causa hipopotasemia, y el temblor fino es el efecto adverso más frecuente. A nivel cardiaco produce taquicardia y palpitaciones, no bradicardia, y se vincula también a hipomagnesemia. Por tanto, hiperkalemia, bradicardia, hipocalcemia y disminución de ácidos grasos libres son lo contrario de lo esperado. Perla clínica: en las crisis graves con dosis repetidas de salbutamol hay que vigilar potasio, glucosa y lactato, porque la acidosis láctica tipo B es una complicación reconocida.",
  f=KAT + "; Goodman y Gilman Las bases farmacológicas de la terapéutica 14.ª ed. (2023); " + GIN)

Q(a="neumologia", cat="Fisiología", tema="Parámetro espirométrico disminuido en asma", año=2016, ext=False,
  e="Varón de 18 años presenta tos seca, sensación de opresión en el tórax y disnea intermitente que empeora en el invierno desde hace 2 años. Examen: sibilantes en ambos campos pulmonares. Se sospecha asma bronquial. ¿Qué parámetro de la función pulmonar se encuentra más disminuido en el paciente?",
  o=["Volumen espiratorio forzado en el primer segundo.", "Volumen de reserva inspiratoria.", "Volumen de ventilación pulmonar.", "Capacidad inspiratoria.", "Capacidad vital."], k="A",
  c="El asma es una enfermedad inflamatoria crónica de la vía aérea con obstrucción variable y reversible al flujo espiratorio, hiperreactividad bronquial y síntomas de tos, sibilancias, disnea y opresión torácica que suelen ser nocturnos o estacionales. En la espirometría el patrón es obstructivo: la limitación al flujo aéreo reduce sobre todo el volumen espiratorio forzado en el primer segundo (VEF1), más que la capacidad vital forzada, de modo que la relación VEF1/CVF cae por debajo de 0,70 (o por debajo del límite inferior de la normalidad). El diagnóstico se apoya en demostrar reversibilidad con un aumento del VEF1 de al menos 12 % y 200 mL tras broncodilatador, o variabilidad del flujo espiratorio máximo mayor de 10 %. El volumen de reserva inspiratoria, el volumen corriente y la capacidad inspiratoria se modifican poco, aunque en las crisis hay atrapamiento aéreo con aumento del volumen residual y de la capacidad pulmonar total y reducción secundaria de la capacidad vital. En los patrones restrictivos, en cambio, disminuyen la capacidad vital y la capacidad pulmonar total con una relación VEF1/CVF normal o elevada. Perla clínica: una espirometría normal no excluye el asma si el paciente está asintomático, y entonces se recurre a la prueba de broncoprovocación con metacolina.",
  f=GIN + "; ATS/ERS, interpretación de pruebas de función pulmonar (Eur Respir J 2022;60:2101499); " + GUY,
  nota="El enunciado del libro dice «de reserva inspiratoria» en B; se mantiene tal cual. Cita ATS/ERS 2022 de interpretación espirométrica a confirmar por el coordinador.")

Q(a="neumologia", cat="Asma", tema="Asma intermitente: tratamiento de elección", año=2017, ext=False,
  e="Varón de 10 años presenta «silbidos de pecho» ocasionales y tos seca una vez por semana o con cambios estacionales. Niega síntomas nocturnos. Antecedente: madre y hermano asmáticos. Examen: sibilantes espiratorios escasos, sin aleteo nasal ni retracciones. Espirometría: patrón obstructivo reversible. Volumen espiratorio forzado en el primer segundo mayor de 80 %. ¿Cuál es el tratamiento de elección?",
  o=["Metilxantina por vía oral.", "Inhibidor de leucotrienos por vía oral.", "Corticosteroide inhalado.", "Antimuscarínico inhalado.", "Beta-2 adrenérgico inhalado."], k="E",
  c="Se trata de un asma leve e intermitente: síntomas menos de dos veces por semana según la clasificación clásica, sin despertares nocturnos, sin limitación de actividad y con función pulmonar conservada (VEF1 mayor de 80 %). El antecedente familiar de asma y la reversibilidad espirométrica apoyan el diagnóstico. En este nivel de gravedad el tratamiento de rescate es un agonista beta-2 de acción corta inhalado (salbutamol), a demanda, administrado con cámara espaciadora, porque brinda la broncodilatación más rápida y eficaz con menos efectos adversos que la vía oral. Los corticoides inhalados diarios se reservan para el asma persistente, y los antileucotrienos son una alternativa de segunda línea en niños que no toleran o rechazan los corticoides. Las metilxantinas casi no se usan por su estrecho margen terapéutico, y los antimuscarínicos como el ipratropio se agregan a las crisis moderadas o graves, nunca como monoterapia de elección. La técnica inhalatoria y el control ambiental (ácaros, humo de tabaco, mascotas) son parte del plan, junto con un plan de acción por escrito. Perla clínica: si el niño usa el beta-2 más de dos veces por semana, o despierta por la noche, hay que reclasificar y pasar a un controlador.",
  f=GIN + "; Nelson Tratado de Pediatría 22.ª ed. (2024); " + HAR,
  nota="El enunciado del libro dice «volumen espiratorio forzado al minuto»; se corrigió a «primer segundo». La clave E sigue la clasificación clásica por frecuencia; GINA 2025 sugiere en niños de 6-11 años considerar un corticoide inhalado a dosis bajas cada vez que se use el beta-2 de rescate (paso 1), así que la pregunta es vulnerable a esa actualización.")

Q(a="neumologia", cat="Asma", tema="Tríada fisiopatológica del asma", año=2017, ext=False,
  e="La tríada fisiopatológica del asma bronquial se caracteriza por:",
  o=["Broncoespasmo, edema de la mucosa e hipersecreción bronquial.", "Broncoconstricción, sangrado de la mucosa y broncorrea.", "Broncoespasmo, flogosis de la mucosa y escasa secreción bronquial.", "Broncoconstricción, mucosa con descamación epitelial y broncorrea.", "Broncoespasmo, edema de la mucosa y secreción mucopurulenta."], k="A",
  c="El asma es una enfermedad inflamatoria crónica de la vía aérea, mediada sobre todo por una respuesta inmunitaria de tipo 2 con participación de mastocitos, eosinófilos y linfocitos Th2, que libera histamina, leucotrienos cisteínicos, prostaglandinas e interleucinas 4, 5 y 13. Estos mediadores producen los tres componentes que explican la obstrucción: contracción del músculo liso bronquial o broncoespasmo, edema de la pared por aumento de la permeabilidad vascular y e inflamación, e hipersecreción de moco por hiperplasia de las células caliciformes y de las glándulas submucosas, que en las crisis graves forma tapones mucosos y se asocia al «asma fatal». A largo plazo hay remodelación con engrosamiento de la membrana basal, hipertrofia del músculo liso y fibrosis subepitelial, que explica la obstrucción parcialmente irreversible. El sangrado de la mucosa no forma parte de la tríada, la descamación epitelial es un hallazgo histológico (cuerpos de Creola, espirales de Curschmann, cristales de Charcot-Leyden) pero no un componente de la tríada clásica, y la secreción es mucosa y espesa, no mucopurulenta, salvo que exista sobreinfección. Perla clínica: el broncoespasmo responde al beta-2 agonista, pero el edema y el moco requieren tratamiento antiinflamatorio, por eso el corticoide es la base del control.",
  f=GIN + "; " + HAR + "; " + ROB)

Q(a="neumologia", cat="Farmacología", tema="Antihipertensivo contraindicado en asma", año=2017, ext=False,
  e="¿Qué antihipertensivo está contraindicado en un hipertenso con antecedente de asma?",
  o=["Atenolol.", "Enalapril.", "Amlodipino.", "Valsartán.", "Metildopa."], k="A",
  c="Los betabloqueadores bloquean los receptores beta-2 del músculo liso bronquial, que median la broncodilatación por las catecolaminas; al antagonizarlos dejan sin oposición el tono colinérgico y precipitan broncoespasmo, a veces grave y refractario al salbutamol. Los no selectivos (propranolol, nadolol, timolol, incluso en colirio) están contraindicados en asma, y los cardioselectivos como atenolol, metoprolol y bisoprolol conservan cierta selectividad que se pierde a dosis altas, por lo que se consideran contraindicados o de último recurso en el asmático. Los inhibidores de la ECA, como enalapril, provocan tos seca por acumulación de bradicinina pero no broncoconstricción; los antagonistas del receptor de angiotensina (valsartán) son la alternativa cuando aparece la tos; los calcioantagonistas dihidropiridínicos (amlodipino) son seguros y útiles, y la metildopa, de acción central, no afecta la vía aérea. En el hipertenso con asma las opciones preferidas son IECA o ARA II, calcioantagonistas y tiazidas, según la comorbilidad. Perla clínica: la contraindicación del betabloqueador también alcanza a la EPOC reactiva y a los colirios de timolol, que pueden precipitar crisis asmáticas.",
  f=KAT + "; ESH, guías de hipertensión arterial (J Hypertens 2023;41:1874-2071); " + GIN,
  nota="Cita ESH 2023 a confirmar por el coordinador (no verificada en línea por mí).")

Q(a="neumologia", cat="Neumonía pediátrica", tema="Signo de gravedad en neumonía infantil tras la taquipnea", año=2017, ext=False,
  e="¿Cuál es el signo de agravamiento en niños con neumonía adquirida en la comunidad que sigue inmediatamente después del incremento de la frecuencia respiratoria?",
  o=["Retracción torácica.", "Estridor inspiratorio.", "Aleteo nasal.", "Cianosis.", "Quejido espiratorio."], k="A",
  c="En la neumonía infantil la taquipnea es el signo más precoz y sensible, y se define según la edad: 50 o más respiraciones por minuto de 2 a 11 meses, 40 o más de 12 meses a 5 años, y 60 o más por debajo de 2 meses (para los menores de dos meses se considera ya enfermedad grave). El esquema de la Atención Integrada de las Enfermedades Prevalentes de la Infancia clasifica como neumonía a la tos con taquipnea, y a la presencia de tiraje subcostal, o retracción torácica inferior, como neumonía grave: es el signo que sigue a la taquipnea porque refleja el aumento del trabajo respiratorio por pérdida de la distensibilidad pulmonar. Los signos de peligro generales, como cianosis central, incapacidad para beber, convulsiones, letargo, estridor en reposo y saturación menor de 90 %, aparecen más tarde e indican enfermedad muy grave con necesidad de hospitalización y oxígeno. El aleteo nasal y el quejido espiratorio son también señales de dificultad respiratoria avanzada. El estridor inspiratorio sugiere obstrucción de la vía aérea superior (crup, cuerpo extraño) y no es un signo de neumonía. Perla clínica: la neumonía lobar sin tiraje con taquipnea simple se trata ambulatoriamente con amoxicilina oral a dosis altas, mientras que la neumonía grave exige internamiento.",
  f="OMS, Revised WHO classification and treatment of childhood pneumonia at health facilities (2014); Nelson Tratado de Pediatría 22.ª ed. (2024); " + HAR,
  nota="Cita de la OMS (2014) tomada de su publicación oficial, sin verificar en PubMed; no se encontró NTS/guía peruana de neumonía infantil con número verificable.")

Q(a="neumologia", cat="Oncología torácica", tema="Metaplasia escamosa en carcinoma epidermoide", año=2018, ext=False,
  e="Varón de 50 años con baja de peso y tos productiva. Antecedentes: consumo de cigarrillos desde los 15 años. Luego de evaluación y estudios se diagnostica carcinoma epidermoide pulmonar. En estadios iniciales del cáncer, ¿a qué tipo de epitelio se transforma el epitelio pseudoestratificado cilíndrico?",
  o=["Estratificado escamoso.", "Simple cilíndrico.", "Simple cúbico.", "Simple granular.", "Poliestratificado mucinoso."], k="A",
  c="El epitelio respiratorio normal de los bronquios es pseudoestratificado cilíndrico ciliado con células caliciformes. Frente a una agresión crónica como el humo del tabaco, la mucosa se adapta mediante metaplasia escamosa: las células basales reemplazan al epitelio original por un epitelio estratificado plano, más resistente a la agresión pero sin cilios ni mucosecreción, con pérdida del aclaramiento mucociliar. Si persiste el estímulo carcinógeno aparecen displasia, carcinoma in situ y carcinoma invasivo, una secuencia con acumulación de alteraciones genéticas (pérdida de 3p, mutaciones de TP53 y de CDKN2A). El carcinoma epidermoide, o de células escamosas, tiene localización central o hiliar, produce tos, hemoptisis y obstrucción bronquial con atelectasia, tiende a cavitarse y puede causar hipercalcemia paraneoplásica por secreción de péptido relacionado con la parathormona. Histológicamente se reconocen queratinización y puentes intercelulares, con inmunohistoquímica p40 y p63 positiva. El epitelio cúbico simple, el cilíndrico simple y otros no representan la respuesta adaptativa de la vía aérea. El adenocarcinoma, en cambio, se origina periféricamente y es el tipo más frecuente en no fumadores y mujeres. Perla clínica: la metaplasia escamosa es reversible si se suspende el tabaco, por eso la cesación es la medida preventiva clave.",
  f="WHO Classification of Thoracic Tumours, 5.ª ed. (2021); " + ROB + "; " + HAR)
